    ["animate_08/text/text_07/text_09"] = "wind",
    ["animate_08/text/text_07/text_08"] = "cries",
    ["animate_10/text/text_07"] = "Only in a moment,",
    ["animate_10/text/text_08"] = [[
the walls turned into some        
powder and were blown to the whole world.]],
    ["animate_10/text/text_08/text_08"] = [[
the walls turned into some        
powder and were blown to the whole world.]],
    ["animate_10/text/text_08/text_02"] = "Black",
    ["animate_10/text/text_08/text_01"] = " ",
    ["animate_10/text/text_09"] = "I closed my",
    ["animate_10/text/text_09/text_09"] = "I closed my",
    ["animate_10/text/text_09/text_10"] = "eyes",
    ["animate_11/text2/text_08"] = "my body drifting in the air along with the powder",
    ["animate_11/text2/text_09"] = "at the end of",
    ["animate_11/text2/text_09/text_09"] = "at the end of",
    ["animate_11/text2/text_09/text_10"] = "the universe",
    ["animate_11/text2/text_09/text_10/text_11"] = " "
  },
  animate115 = {
    ["animate_01/text/text_01"] = "Through the fog and clouds,",
    ["animate_01/text/text_02"] = "I kept",
    ["animate_01/text/text_02/text_02 (1)"] = "falling,",
    ["animate_01/text/text_03"] = "like a bird",
    ["animate_01/text/text_03/text_03 (1)"] = "with a broken wing",
    ["animate_01/text/text_04"] = "The fog dispersed.I was stuck between grey walls,",
    ["animate_01/text/text_05"] = "with countless threads scattered around.",
    ["animate_01/text/text_06"] = "I tried to",
    ["animate_01/text/text_06/text_06 (1)"] = " escape,",
    ["animate_01/text/text_07"] = "but soft threads turned into the sharpest ",
    ["animate_01/text/text_07/text_07 (1)"] = "blades",
    ["animate_01/text/text_08"] = "A droop of scarlet ",
    ["animate_01/text/text_08/text_08(1)"] = "blood",
    ["animate_01/text/text_09"] = "slid off my arms.",
    ["animate_02/text/text_01"] = "Suddenly,",
    ["animate_02/text/text_01/text_01 (1)"] = "the world began to shake,",
    ["animate_02/text/text_02"] = "The grey walls                             bit by bit.",
    ["animate_02/text/text_02/text_01 (1)"] = "collapsed",
    ["animate_02/text/text_03"] = "A fierce wind               the threads.",
    ["animate_02/text/text_03/text_01 (1)"] = "tore",
    ["animate_02/text/text_04"] = "A                         shadow",
    ["animate_02/text/text_04/text_01 (1)"] = "broken",
    ["animate_02/text/text_05"] = "appeared right before me."
  },
  animate116 = {
    ["animate_01/text/text_01"] = "Under a deep blue sky,",
    ["animate_01/text/text_02"] = "I stood on the edge of a                               ,",
    ["animate_01/text/text_02/text_02 (1)"] = "steep cliff",
    ["animate_01/text/text_03"] = "with someone's arms                    around me,",
    ["animate_01/text/text_03/text_03 (1)"] = "tightly",
    ["animate_01/text/text_04"] = "familiar",
    ["animate_01/text/text_04/text_04 (1)"] = " yet ",
    ["animate_01/text/text_04/text_04 (2)"] = "strange.",
    ["animate_01/text/effect_text_03/text_03 (1)"] = "with someone's arms                   around me,",
    ["animate_01/text/effect_text_03/text_03 (1)/text_03 (1)"] = "tightly",
    ["animate_02/text/text_05"] = "His face was blurry,",
    ["animate_02/text/text_05/text_05 (1)"] = "",
    ["animate_02/text/text_05/text_05 (2)"] = "",
    ["animate_02/text/text_06"] = "but his eyes were like",
    ["animate_02/text/text_06/text_06 (1)"] = "",
    ["animate_02/text/text_07"] = "ocean deep",
    ["animate_02/text/text_07/text_07 (1)"] = " and",
    ["animate_02/text/text_07/text_07 (2)"] = " crystal clear",
    ["animate_02/text/text_07/text_07 (3)"] = ".",
    ["animate_03/text/text_08"] = "Rocks near my feet fell, causing                                .",
    ["animate_03/text/text_08/text_08 (1)"] = "vibration",
    ["animate_03/text/text_09"] = "His clothes billowing in the                  ,",
    ["animate_03/text/text_09/text_09 (1)"] = "wind",
    ["animate_03/text/text_10"] = "he held me and jumped off the edge.",
    ["animate_03/text/text_10/text_10 (1)"] = "",
    ["animate_03/text/text_11"] = "Who... is him?",
    ["animate_03/text/text_11/text_11 (1)"] = "",
    ["animate_03/text/text_11/text_11 (2)"] = "",
    ["animate_03/text/text_11/text_11 (3)"] = "..",
    ["animate_03/text/text_11/text_11 (4)"] = "...."
  },
  animate117 = {
    ["animate_01/text/text_01"] = "Under the dim sky,",
    ["animate_01/text/text_02"] = "the city was covered in dark clouds.",
    ["animate_01/text/text_03"] = "The halo in the sky",
    ["animate_01/text/text_04"] = "was like a raindrop                    .",
    ["animate_01/text/text_04/text_04 (1)"] = "ripple",
    ["animate_02/text/text_01"] = "I looked down and saw under the still water,",
    ["animate_02/text/text_02"] = "the square decorated with colorful lights.",
    ["animate_02/text/text_03"] = "I saw the figure of                               ,",
    ["animate_02/text/text_03/text_03 (1)"] = "my own",
    ["animate_02/text/text_04"] = "against the light, smiling at me."
  },
  animate118 = {
    ["animate_01/text/text_01"] = "The endless wind swallowed me.",
    ["animate_01/text/text_02"] = "The darkest abyss clutch at me.",
    ["animate_01/text/text_02/text_03"] = "",
    ["animate_2/text/text_01"] = "I was asleep floating at the end of the world,",
    ["animate_2/text/text_01/text_01 (1)"] = "",
    ["animate_2/text/text_02"] = "without destination,",
    ["animate_2/text/text_02/text_02 (1)"] = "",
    ["animate_2/text/text_03"] = "without direction.",
    ["animate_2/text/text_03/text_03 (1)"] = "",
    ["animate_2/text/text_03/text_03 (2)"] = "",
    ["animate_03/text/text_01"] = "Who",
    ["animate_03/text/text_01/text_01 (1)"] = "illumined",
    ["animate_03/text/text_01/text_01 (2)"] = "the",
    ["animate_03/text/text_01/text_01 (3)"] = "only",
    ["animate_03/text/text_01/text_01 (4)"] = "source",
    ["animate_03/text/text_01/text_01 (5)"] = " of",
    ["animate_03/text/text_01/text_01 (6)"] = " light?",
    ["animate_03/text/text_01/text_01 (7)"] = "",
    ["animate_03/text/text_02"] = "Moved the second hand.",
    ["animate_03/text/text_03"] = "Wherever             are, I'll come to find you.",
    ["animate_03/text/text_03/text_03 (1)"] = "you",
    ["animate_03/text/effect_text_03/text_03 (2)"] = "Wherever             are, I'll come to find you.",
    ["animate_03/text/effect_text_03/text_03 (2)/text_03 (1)"] = "you",
    ["animate_04/text/text_01"] = "Confined in the giant cell for too long,",
    ["animate_04/text/text_01/text_01 (1)"] = "",
    ["animate_04/text/text_02"] = "I opened my eyes."
  },
  animate119 = {
    ["animate_01/text/text_01"] = "It's snowing          ",
    ["animate_01/text/text_01/text_02"] = "......",
    ["animate_01/text/text_03"] = "I walked alone on the open moors.",
    ["animate_01/text/text_04"] = "A heavy snow ",
    ["animate_01/text/text_05"] = "with glowing lights",
    ["animate_01/text/text_06"] = "slowly and quietly,",
    ["animate_01/text/text_07"] = "covers all the                and ",
    ["animate_01/text/text_07/text_08"] = "shade",
    ["animate_01/text/text_07/text_06"] = "colors",
    ["animate_02/text/text_09"] = "Light spots floating around me,",
    ["animate_02/text/text_10"] = "I reached out to catch a snowflake,",
    ["animate_02/text/text_11"] = "In the snow crystal reflected",
    ["animate_02/text/text_12"] = "a colorful world."
  },
  animate120 = {
    ["animate_01/text/text_01"] = "\"BANG\"",
    ["animate_01/text/text_02"] = "The city was like ",
    ["animate_01/text/text_03"] = "          a broken mirror.",
    ["animate_01/text/text_04"] = "Shards floating in the air ",
    ["animate_01/text/text_05"] = "reflected dreamy and colorful lights.",
    ["animate_01/text/text_06"] = "The darkness behind it was",
    ["animate_01/text/text_06/text_06_01"] = "my worst nightmare.",
    ["animate_02/text/text_07"] = "Countless doors glimmering",
    ["animate_02/text/text_08"] = "stretch from the abyss to the sky",
    ["animate_02/text/text_09"] = "Make your choice.  ",
    ["animate_02/text/text_10"] = "Someone in the void says to me.",
    ["animate_02/text/text_11"] = "I stepped forward,",
    ["animate_02/text/text_12"] = "and touched the door in front.",
    ["animate_02/text/text_13"] = "Strong lights devoured me.\nHave you found?\n— the real truth. "
  },
  animate122 = {
    ["animate_01/text/text_01"] = "We groped forward in the narrow space",
    ["animate_01/text/text_02"] = "Cold inorganic sound somehow mingled among the footsteps",
    ["animate_01/text/text_03"] = "Machines with metallic luster                                                                        ",
    ["animate_01/text/text_03/text_03_01"] = "suddenly approached",
    ["animate_01/text/text_03/text_03_01/text_03_02"] = "and",
    ["animate_01/text/text_04"] = "Greedily robbed me of the only light spot in front of me",
    ["animate_02/text/text_01"] = "Black hurricane rapidly rose and swept",
    ["animate_02/text/text_02"] = "As if wanting to hold on to the last hope",
    ["animate_02/text/text_03"] = "Yet eroding everything ",
    ["animate_02/text/text_04"] = "at the same time"
  },
  animate123 = {
    ["animate_01/text/text_01"] = "The undercurrents",
    ["animate_01/text/text_02"] = "Swirled under my feet",
    ["animate_01/text/text_03"] = "I stepped back in panic",
    ["animate_02/text/text_01"] = "But felt the sticky dampness",
    ["animate_02/text/text_02"] = " turning into piercing coldness",
    ["animate_02/text/text_03"] = "The frozen seawater",
    ["animate_02/text/text_03/text_03_01"] = [[




collapsed little by little ]],
    ["animate_02/text/text_03/text_03_02"] = "",
    ["animate_02/text/text_03/text_03_03"] = "",
    ["animate_02/text/text_03/text_03_04"] = "",
    ["animate_02/text/text_04"] = "Until it vanished without a trace"
  },
  animate124 = {
    ["animate_01/text/text_01"] = "All of us gave our best",
    ["animate_01/text/text_02"] = "We have nothing left",
    ["animate_01/text/text_03"] = "At the end of the world",
    ["animate_01/text/text_04"] = "At ",
    ["animate_01/text/text_04/text_04_01"] = "the end of time",
    ["animate_01/text/text_05"] = "I will wait together with you",
    ["animate_01/text/text_06"] = "For the arrival of doomsday"
  },
  animate125 = {
    ["animate_01/text/text_01"] = "From the end to the exit",
    ["animate_01/text/text_02"] = "From here to there",
    ["animate_01/text/text_03"] = "For each step I take",
    ["animate_01/text/text_04"] = "I will no longer hesitate.",
    ["animate_01/text/text_05"] = "Someone is waiting for me",
    ["animate_01/text/text_06"] = "I must return there."
  },
  animate127 = {
    ["animate_01/text/text_01"] = "Someone's watching from afar",
    ["animate_01/text/text_02"] = "Someone's struggling in the flames",
    ["animate_01/text/text_03"] = "Someone's waiting by the shore",
    ["animate_01/text/text_04"] = "Someone grabbed my hand",
    ["animate_01/text/text_05"] = "This time",
    ["animate_01/text/text_06"] = "I will find you."
  },
  animate135 = {
    ["BG_01/text_01/text_01"] = "Rainstorms, lightnings,",
    ["BG_01/text_01/text_01/text_01 (1)"] = "Rainstorms, lightnings,",
    ["BG_01/text_01/text_01/text_02"] = "hurricanes, earthquakes...",
    ["BG_01/text_01/text_01/text_02/text_01 (2)"] = "hurricanes, earthquakes...",
    ["BG_01/text_01/text_03"] = "Amid the rise of extreme weather conditions and natural castastrophes,",
    ["BG_01/text_01/text_03/text_04"] = "a prophecy is spreading in the dark --",
    ["BG_01/text_02/text_01"] = "The two daughters of the world",
    ["BG_01/text_02/text_02"] = "One rises toward",
    ["BG_01/text_02/text_02/text_02 (1)"] = "Light,",
    ["BG_01/text_02/text_03"] = "the other plunges into",
    ["BG_01/text_02/text_03/text_03 (1)"] = "Darkness",
    ["BG_01/text_02/text_04"] = "The angel with the sword in his left hand",
    ["BG_01/text_02/text_05"] = "will pierce through the veil of lies.",
    ["BG_01/text_03/text_06"] = "Everyone is eager to return to the peaceful days",
    ["BG_01/text_03/text_07"] = "But the halted feet will move forward, until...",
    ["BG_01/text_03/text_08"] = "the moment of",
    ["BG_01/text_03/text_08/text_08 (1)"] = "It's arrival.",
    ["BG_01/text_03/text_09"] = "he moment of",
    ["BG_01/text_03/text_09/text_08 (1)"] = "It's arrival."
  },
  animate137 = {
    ["text/text_01_05"] = "It was a huge door I'd never seen before",
    ["pic_01/text_01/text_01_01"] = "When I opened my eyes again",
    ["pic_01/text_01/text_01_02"] = "I was shrouded in a glowing white light",
    ["pic_01/text_01/text_01_03"] = "I couldn't tell where I was",
    ["pic_01/text_01/text_01_04"] = "There was just one shining point of light at the end  It seemed to be waiting for me",
    ["pic_02/text_02/text_01_01"] = "I started sprinting toward it",
    ["pic_02/text_02/text_01_02"] = "Each step firm and strong",
    ["pic_02/text_02/text_01_03"] = "It was right in front of me,  but seemed to take a century to reach",
    ["pic_03/text_03/text_01_01"] = "Finally --",
    ["pic_03/text_03/text_01_02"] = "I made contact with the door",
    ["pic_04/text_04/text_01_01"] = "The hands upon the door were small",
    ["pic_04/text_04/text_01_02"] = "I found it a bit strange",
    ["pic_05/text_05/text_01_01"] = "And at the same time",
    ["pic_05/text_05/text_01_02"] = "the door was pushed open"
  },
  anime_bg_5 = {
    lblTip = "*Clear all the stages of the chapter to switch character"
  },
  anime_bg_7 = {
    lblTip = "*Re-enter the section to switch character"
  },
  cartoon_001 = {
    ["chapter_01/text_01"] = "With courage of the two",
    ["chapter_01/text_02"] = "I kept moving forward in the                                            space",
    ["chapter_01/text_02/text_02 (1)"] = "pitch-dark",
    ["chapter_04/text_05"] = "At the end of the darkness",
    ["chapter_04/text_06"] = "I saw a door, the last door",
    ["chapter_04/text_07"] = "Opening slowly towards me",
    ["chapter_05/text_08"] = "No longer hesitant",
    ["chapter_05/text_09"] = "I stepped towards the one and only reality",
    ["chapter_08/text_16"] = "Endless agony had becomemy resolution to end everything,once and for all",
    ["chapter_08/text_17"] = "Something surged inside me",
    ["chapter_08/text_18"] = "Trying to break out",
    ["chapter_20/bg/text_37"] = "In the void",
    ["chapter_20/bg/text_38"] = "I saw the only future that this worldwas destined to have",
    ["chapter_21/text_39"] = "This world",
    ["chapter_21/text_40"] = "The last prophecy of fate"
  },
  pw_animate001 = {
    ["animate_01/text/text_01"] = "When you fell,",
    ["animate_01/text/text_02"] = "It was like the setting moon in a forest.",
    ["animate_01/text/text_03"] = "Rays splashed and gleamed,",
    ["animate_01/text/text_04"] = "Then feathers fell to dust.",
    ["animate_01/text/text_05"] = "That was your choice,",
    ["animate_01/text/text_06"] = "And also my fate.",
    ["animate_01/text/text_07"] = "If we should meet again,",
    ["animate_01/text/text_08"] = "I hope I can take your hand.",
    ["animate_01/text/text_09"] = "—And return with you."
  },
  pw_animate002 = {
    ["animate_01/text/text_01"] = "You are my only dream.",
    ["animate_01/text/text_02"] = "Wind shook the grove that day,",
    ["animate_01/text/text_03"] = "And I passed by a pleasant dream.",
    ["animate_01/text/text_04"] = "Then feathers fell to dust.",
    ["animate_01/text/text_05"] = "That was your choice,",
    ["animate_01/text/text_06"] = "And also my fate.",
    ["animate_01/text/text_07"] = "If we should meet again,",
    ["animate_01/text/text_08"] = "I hope I can take your hand.",
    ["animate_01/text/text_09"] = "—And return with you."
  },
  pw_animate003 = {
    ["animate_01/text/text_01"] = "The cave was windless that day.",
    ["animate_01/text/text_02"] = "You were a            shining on fate.",
    ["animate_01/text/text_02/text_02 (1)"] = "light",
    ["animate_01/text/text_03"] = "A chance agreement. Destiny of a sword.",
    ["animate_01/text/text_04"] = "If our fate is                                                                             ,",
    ["animate_01/text/text_04/text_04 (1)"] = "blood-stained",
    ["animate_01/text/text_05"] = "Then let us fight on together.",
    ["animate_01/text/text_06"] = "This is the sword I borrowed from you.",
    ["animate_01/text/text_07"] = "One day, I shall return it to you.",
    ["animate_01/text/text_08"] = "—Along with my              , together.",
    ["animate_01/text/text_08/text_08 (1)"] = "life"
  },
  houseanimate101 = {
    ["text/001/Label"] = "The sunlight poured  down",
    ["text/002/Label"] = "Sweeping away the last shadows",
    ["text/003/Label"] = "In this cozy little house",
    ["text/004/Label"] = "The person you want to see most Is..."
  },
